# Last checks. REV_MUT and FRM_ARM select the build.
source("dev/review-nlfix-common.R")
`%||%` <- function(a, b) if (is.null(a)) b else a
ll <- function(r) if (iserr(r)) paste("ERR", substr(r$msg, 1, 240)) else paste0(format(as.numeric(logLik(r)), digits = 10), " conv=", r$opt$convergence, " beta=", paste(format(r$estimates$beta, digits = 4), collapse = ","), " w=", length(attr(r, "w")), if (length(attr(r, "w"))) paste0(" [", substr(attr(r, "w")[1], 1, 170), "]"))
set.seed(4401)
n <- 200
d <- data.frame(x = rnorm(n), z = rnorm(n), g = factor(rep(1:10, each = 20)), t = rep(1:20, 10))
d$y <- 1 + 0.5 * d$x + ave(rnorm(n, 0, 0.5), d$g, FUN = function(z) as.numeric(stats::filter(z, 0.5, "recursive")))
d$y2 <- 0.3 * d$z + rnorm(n)
d$gg <- factor(rep(c("p", "q"), length.out = n))
d$yo <- cut(0.8 * d$x + rlogis(n), c(-Inf, -1, 0, 1, Inf), labels = 1:4, ordered_result = TRUE)
st <- list(beta = c("a_(Intercept)" = 1, "b_(Intercept)" = 0.5))
cat("--- a user's helper named cs in a body\n")
cs <- function(x) x^2
f1 <- bf(y ~ a * cs(x), a ~ 1, nl = TRUE)
cat(ll(tt(frm(f1, data = d))), "\n")
cat("linear equivalent:", ll(tt(frm(y ~ 0 + I(x^2), data = d))), "\n")
rm(cs)
sq <- function(x) x^2
cat("control, helper named sq:", ll(tt(frm(bf(y ~ a * sq(x), a ~ 1, nl = TRUE), data = d))), "\n")
cat("--- large response warning, in full\n")
d$ybig <- 1e6 + 5e4 * d$x + rnorm(n, 0, 1e3)
r <- tt(frm(bf(ybig ~ a + b * x, a + b ~ 1, nl = TRUE), data = d)); cat(ll(r), "\n"); cat(attr(r, "w"), "\n")
if (arm == "before") { cat("--- frm_curve on a linear cov = FALSE\n"); fl <- frm(bf(y ~ x, autocor = ~ ar(time = t, gr = g, cov = FALSE)), data = d); x <- tt(frm_curve(fl, newdata = d[1:3, ])); show("frm_curve", if (iserr(x)) x else 1); quit("no") }
cat("--- conditional_effects values, cov = FALSE and TRUE\n")
for (cv in c(FALSE, TRUE)) {
  fn <- suppressWarnings(frm(bf(y ~ a + b * x, a + b ~ 1, nl = TRUE, autocor = ~ ar(time = t, gr = g, cov = cv)), data = d, start = st))
  fl <- suppressWarnings(frm(bf(y ~ x, autocor = ~ ar(time = t, gr = g, cov = cv)), data = d))
  a <- tt(conditional_effects(fn, effects = "x")[[1]]); b <- tt(conditional_effects(fl, effects = "x")[[1]])
  cat("cov =", cv, " estimate diff:", if (iserr(a) || iserr(b)) paste(a$msg, b$msg) else max(abs(a$estimate__ - b$estimate__)), " upper diff:", if (iserr(a) || iserr(b)) "" else max(abs(a$upper__ - b$upper__)), "\n")
}
cat("--- multivariate with a term on one body\n")
m1 <- tt(frm(mvbf(bf(y ~ a + b * x, a + b ~ 1, nl = TRUE, autocor = ~ ar(time = t, gr = g, cov = TRUE)), bf(y2 ~ z), rescor = FALSE), data = d, start = list(beta = c("y_a_(Intercept)" = 1, "y_b_(Intercept)" = 0.5))))
s1 <- as.numeric(logLik(frm(bf(y ~ x, autocor = ~ ar(time = t, gr = g, cov = TRUE)), data = d))) + as.numeric(logLik(frm(y2 ~ z, data = d)))
cat("mv with term:", ll(m1), " sum of separate:", s1, "\n")
b1 <- tryCatch(nchar(as.character(brms::stancode(brms::mvbf(brms::bf(y ~ a + b * x, a + b ~ 1, nl = TRUE, autocor = ~ ar(time = t, gr = g, cov = TRUE)), brms::bf(y2 ~ z), rescor = FALSE), data = d))), error = function(e) conditionMessage(e)); cat("brms:", b1, "\n")
m2 <- tt(frm(bf(y ~ a + b * x, a + b ~ 1, nl = TRUE) + bf(y2 ~ z) + set_rescor(FALSE) + acformula(~ ar(time = t, gr = g, cov = TRUE), resp = "y"), data = d, start = list(beta = c("y_a_(Intercept)" = 1, "y_b_(Intercept)" = 0.5))))
cat("mv + acformula(resp =):", ll(m2), "\n")
cat("--- update with formula. on an nl fit with a term, and the stored call (ac_refit)\n")
fn <- suppressWarnings(frm(bf(y ~ a + b * x, a + b ~ 1, nl = TRUE, autocor = ~ ar(time = t, gr = g, cov = TRUE)), data = d, start = st))
u <- tt(update(fn, formula. = bf(y ~ a + b * z, nl = TRUE, autocor = ~ ar(time = t, gr = g, cov = TRUE)), start = st))
cat("update formula. :", ll(u), "\n")
if (!iserr(u)) { u2 <- tt(update(u, data = d[d$g != 1, ], start = st)); cat(" then update data:", ll(u2), " term kept:", if (!iserr(u2)) length(u2$frame[["autocor"]]) > 0 else NA, "\n"); print(u$call$formula %||% u$call[[2]]) }
uo <- tt(update(fn, formula. = bf(y ~ a + b * z, nl = TRUE), start = st)); cat("update formula. without the term:", ll(uo), " term kept:", if (!iserr(uo)) length(uo$frame[["autocor"]]) > 0 else NA, "\n")
ul <- tt(update(suppressWarnings(frm(bf(y ~ x, autocor = ~ ar(time = t, gr = g, cov = TRUE)), data = d)), formula. = bf(y ~ z))); cat("linear: update formula. without the term:", ll(ul), " term kept:", if (!iserr(ul)) length(ul$frame[["autocor"]]) > 0 else NA, "\n")
cat("--- nl = FALSE on a formula that holds a term in the slot\n")
b0 <- bf(y ~ a + b * x, a + b ~ 1, nl = TRUE, autocor = ~ ar(time = t, gr = g, cov = TRUE))
b1 <- tt(bf(b0, nl = FALSE)); print(if (iserr(b1)) b1$msg else b1)
cat("--- prior tables against brms on an ordinal body\n")
cmp <- function(lab, ff, fb, fam, famb) {
  a <- as.data.frame(tt(get_prior(ff, data = d, family = fam, route = "sample"))); if (!"prior" %in% names(a)) a <- as.data.frame(tt(get_prior(ff, data = d, family = fam)))
  b <- as.data.frame(brms::default_prior(fb, data = d, family = famb))
  key <- function(z) sort(paste(z$class, z$coef, z$group, z$dpar, z$nlpar, sep = "/"))
  cat(lab, ": rows frm", nrow(a), "brms", nrow(b), " only frm:", paste(setdiff(key(a), key(b)), collapse = " "), " only brms:", paste(setdiff(key(b), key(a)), collapse = " "), "\n")
}
cmp("plain", bf(yo ~ b1 * x, b1 ~ 1, nl = TRUE), brms::bf(yo ~ b1 * x, b1 ~ 1, nl = TRUE), cumulative(), brms::cumulative())
cmp("gr", bf(yo | thres(gr = gg) ~ b1 * x, b1 ~ 1, nl = TRUE), brms::bf(yo | thres(gr = gg) ~ b1 * x, b1 ~ 1, nl = TRUE), cumulative(), brms::cumulative())
cmp("equidistant", bf(yo ~ b1 * x, b1 ~ 1, nl = TRUE), brms::bf(yo ~ b1 * x, b1 ~ 1, nl = TRUE), cumulative(threshold = "equidistant"), brms::cumulative(threshold = "equidistant"))
cmp("disc", bf(yo ~ b1 * x, b1 ~ 1, disc ~ 0 + z, nl = TRUE), brms::bf(yo ~ b1 * x, b1 ~ 1, disc ~ 0 + z, nl = TRUE), cumulative(), brms::cumulative())
cmp("mixture", bf(yo ~ b1 * x, b1 ~ 1, nl = TRUE), brms::bf(yo ~ b1 * x, b1 ~ 1, nl = TRUE), mixture(cumulative(), cumulative()), brms::mixture(brms::cumulative(), brms::cumulative()))
cmp("ar", bf(y ~ a + b * x, a + b ~ 1, nl = TRUE, autocor = ~ ar(time = t, gr = g, cov = TRUE)), brms::bf(y ~ a + b * x, a + b ~ 1, nl = TRUE, autocor = ~ ar(time = t, gr = g, cov = TRUE)), gaussian(), brms::brmsfamily("gaussian"))
cat("--- a prior on thresholds of a body acts\n")
f0 <- frm(bf(yo ~ b1 * x, b1 ~ 1, nl = TRUE), family = cumulative(), data = d)
f1 <- tt(frm(bf(yo ~ b1 * x, b1 ~ 1, nl = TRUE), family = cumulative(), data = d, prior = set_prior("normal(5, 0.1)", class = "Intercept", coef = "1")))
cat(ll(f0), "\n", ll(f1), "\n"); if (!iserr(f1)) print(round(summary(f1)$fixed[1:3, 1], 3))
